            for c in range(1, classes):
                if counts[c] > counts[best]:
                    best = c
            prediction = best
        connection_rows.append({
            "id": conn["id"],
            "split": conn["split"],
            "label": conn["label"],
            "packets": counters[i],
            "votes": counts,
            "prediction": prediction,
        })

    reports = _build_reports(connection_rows, classes)

    return {
        "packets": packet_rows,
        "jobs": jobs,
        "connections": connection_rows,
        "reports": reports,
    }


def _build_reports(connection_rows, classes):
    reports = {}
    for split in ("dev", "eval"):
        confusion = [[0] * classes for _ in range(classes)]
        observed = 0
        for row in connection_rows:
            if row["split"] != split:
                continue
            if row["packets"] <= 0:
                continue
            observed += 1
            confusion[row["label"]][row["prediction"]] += 1
        total = Fraction(0)
        for c in range(classes):
            true_positive = confusion[c][c]
            false_positive = 0
            for r in range(classes):
                false_positive += confusion[r][c]
            false_positive -= true_positive
            false_negative = sum(confusion[c]) - true_positive
            denominator = 2 * true_positive + false_positive + false_negative
            if denominator > 0:
                total += Fraction(2 * true_positive, denominator)
        macro = total / classes
        reports[split] = {
            "connections": observed,
            "confusion": confusion,
            "macro_f1": [macro.numerator, macro.denominator],
        }
    return reports


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------

def _run(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise InvalidInput()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidInput()
    try:
        doc = json.loads(text, object_pairs_hook=_no_duplicate_keys,
                         parse_constant=_reject_constant)
    except InvalidInput:
        raise
    except (ValueError, RecursionError):
        raise InvalidInput()
    config, model, connections, packets = validate_document(doc)
    return replay(config, model, connections, packets)


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        raw = b""
    payload = ERROR_DOC
    try:
        result = _run(raw)
        payload = json.dumps(result, separators=(",", ":"))
    except Exception:
        payload = ERROR_DOC
    try:
        sys.stdout.write(payload)
        sys.stdout.write("\n")
        sys.stdout.flush()
    except Exception:
        pass
    return 0


if __name__ == "__main__":
    sys.exit(main())
